 public static void RemainingGameScreens(){CasinoScreensOnly();SessionState.SetBool(Key+"extraGameScreens",true);}
 static async UniTask AddMissingGameScreens(ParkCasinoIntegration c){var current=completion;var accepted=JsonUtility.FromJson<CompletionReceipt>(File.ReadAllText(Path.Combine(Reports,"screenshot-core-complete.json")));var originalUtc=accepted.utc;completion=accepted;completion.utc=current.utc;completion.notes.Add("47 placed-screen cases and 23 item cases accepted from completed run at "+originalUtc+"; this run adds unselected native game prefab displays");completion.menuCustom=current.menuCustom;completion.menuProxy=current.menuProxy;completion.menuUnsupported=current.menuUnsupported;completion.passed=false;await CompletionFloor(c,4);foreach(string name in new[]{"Baccarat","MineSweeper","Plinko"}){CompleteStage("EXTRA_NATIVE_"+name);int index=Array.FindIndex(CasinoLabSelection.Names,n=>n.Equals(name,StringComparison.OrdinalIgnoreCase)||n.Replace(" ","").Equals(name,StringComparison.OrdinalIgnoreCase));if(index<0)throw new Exception("Native floor 4 loot table lacks "+name+": "+string.Join(",",CasinoLabSelection.Names));SceneManager.SetActiveScene(c.ModuleRoot.gameObject.scene);bool done=false;c.Bootstrap.StartCoroutine(ReplaceDetailed(index,()=>done=true));await Wait(()=>done&&c.Bootstrap.ready&&CasinoLabSelection.SelectedGame,35);SceneManager.SetActiveScene(c.gameObject.scene);var game=CasinoLabSelection.SelectedGame;var pad=game.Keypad;await StandAtPad(c,game);c.RegisterCasinoButtons();pad.SendMessage("RequestRender",SendMessageOptions.DontRequireReceiver);await Pause(.15f);var pixels=ScreenData(pad.keypadCamera.targetTexture);previousPixels[pad.GetInstanceID()]=(CasinoLabBootstrap.Field<TMPro.TextMeshPro>(pad,"displayText").text+"|"+pad.Network_errorMessage,pixels);var q=new CompleteScreen{game=game.GameType.ToString(),floor=4,mask=pad.keypadCamera.cullingMask,brightPixels=pixels.Count(p=>p.a>20&&p.r+p.g+p.b>210),brightFraction=pixels.Count(p=>p.a>20&&p.r+p.g+p.b>210)/(float)pixels.Length};completion.screens.Add(q);await VerifyPad(c,pad);q.actualButtons=true;q.text=CasinoLabBootstrap.Field<TMPro.TextMeshPro>(pad,"displayText").text;var raw=CasinoLabBootstrap.Field<RawImage>(pad,"keypadRenderTarget");foreach(float distance in new[]{.85f,2.5f}){var point=pad.transform.position+pad.transform.forward*distance;point.y=NativeFloorHeight(c,point,pad.transform.position.y+.2f)+.06f;c.HostPlayer.TeleportPlayer(point,true);c.HostPlayer.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.3f);await Aim(c,raw.transform.position);q.supportChecked=true;q.playerFootY=c.HostPlayer.transform.position.y;q.expectedGround=NativeFloorHeight(c,point,pad.transform.position.y+.2f);q.grounded=FeetSupport(c)&&q.playerFootY>=q.expectedGround-.2f;bool visible=CompletionVisible(raw,CasinoRuntimeContext.PlayerCamera);float eye=Vector3.Distance(CasinoRuntimeContext.PlayerCamera.transform.position,raw.transform.position);if(distance<1){q.nearVisible=visible;q.nearDistance=eye;}else{q.midVisible=visible;q.midDistance=eye;}}if(!q.nearVisible||!q.midVisible||!q.grounded||q.mask!=2||q.brightPixels<10||q.brightFraction>.2f)throw new Exception("Extra native display failed "+name);completion.notes.Add("EXTRA_NATIVE_PREFAB "+name+" game="+q.game+" near="+q.nearDistance+" mid="+q.midDistance);CompleteStage("EXTRA_NATIVE_"+name+"_PASS");}await CompletionFloor(c,0);completion.passed=completion.failures.Count==0&&completion.screens.Count==50&&completion.screens.Select(s=>s.game).Distinct().Count()==16&&completion.updates.All(u=>u.passed);CompleteStage(completion.passed?"PASS":"FAILED");}
